from langchain_core.messages import HumanMessage, AIMessage, BaseMessage
from langchain_openai import ChatOpenAI
from langgraph.graph import StateGraph, END
import operator

llm = ChatOpenAI(model=&#34;gpt-4o-mini&#34;)

class ReviewState(TypedDict):
    task: str                                          # 原始任务
    messages: Annotated[List[BaseMessage], operator.add]  # 对话历史
    draft: str                                         # 当前草稿
    critique: str                                      # 最新评审意见
    iteration: int                                     # 当前迭代轮数
    approved: bool                                     # 是否通过评审

# ─── Generator Agent ───
def generator_node(state: ReviewState) -&gt; dict:
    &#34;&#34;&#34;生成或修改方案&#34;&#34;&#34;
    if state[&#34;iteration&#34;] == 0:
        # 第一轮：初始生成
        prompt = f&#34;请为以下任务生成一个详细方案：\n{state[&#39;task&#39;]}&#34;
    else:
        # 后续轮：根据评审意见修改
        prompt = f&#34;&#34;&#34;原始任务：{state[&#39;task&#39;]}

当前草稿：
{state[&#39;draft&#39;]}

评审意见：
{state[&#39;critique&#39;]}

请根据评审意见修改方案，解决所有提出的问题。&#34;&#34;&#34;

    response = llm.invoke([HumanMessage(content=prompt)])
    new_draft = response.content

    print(f&#34;\n[Generator - 第{state[&#39;iteration&#39;]+1}轮] 生成方案（前200字）：&#34;)
    print(new_draft[:200] + &#34;...&#34;)

    return {
        &#34;draft&#34;: new_draft,
        &#34;messages&#34;: [AIMessage(content=f&#34;Generator（第{state[&#39;iteration&#39;]+1}轮）: {new_draft[:100]}...&#34;)],
        &#34;iteration&#34;: state[&#34;iteration&#34;] + 1
    }

# ─── Critic Agent ───
def critic_node(state: ReviewState) -&gt; dict:
    &#34;&#34;&#34;评审当前方案&#34;&#34;&#34;
    prompt = f&#34;&#34;&#34;你是严格的方案评审专家。请评审以下方案：

任务要求：{state[&#39;task&#39;]}

当前方案：
{state[&#39;draft&#39;]}

请从以下维度评审（每点50字以内）：
1. 可行性：方案是否现实可执行？
2. 完整性：是否覆盖了任务的所有要求？
3. 清晰度：逻辑是否清晰，表达是否准确？

最后给出结论：
- 如果方案质量达标（三个维度均无重大问题），回复&#34;APPROVED&#34;
- 否则回复&#34;NEEDS_REVISION&#34;并列出具体改进点&#34;&#34;&#34;

    response = llm.invoke([HumanMessage(content=prompt)])
    critique = response.content
    approved = &#34;APPROVED&#34; in critique

    print(f&#34;\n[Critic - 第{state[&#39;iteration&#39;]}轮评审] {&#39;通过&#39; if approved else &#39;需修改&#39;}&#34;)
    if not approved:
        print(f&#34;改进意见：{critique[:200]}...&#34;)

    return {
        &#34;critique&#34;: critique,
        &#34;approved&#34;: approved,
        &#34;messages&#34;: [AIMessage(content=f&#34;Critic: {&#39;APPROVED&#39; if approved else &#39;NEEDS_REVISION&#39;}&#34;)]
    }

# ─── 路由逻辑 ───
def should_continue(state: ReviewState) -&gt; str:
    &#34;&#34;&#34;判断是继续修改还是结束&#34;&#34;&#34;
    if state[&#34;approved&#34;]:
        return END
    if state[&#34;iteration&#34;] &gt;= 3:     # 最多迭代3次
        print(&#34;\n[系统] 达到最大迭代次数，终止&#34;)
        return END
    return &#34;generator&#34;              # 返回生成器继续修改

# ─── 构建图 ───
workflow = StateGraph(ReviewState)
workflow.add_node(&#34;generator&#34;, generator_node)
workflow.add_node(&#34;critic&#34;,    critic_node)

workflow.set_entry_point(&#34;generator&#34;)
workflow.add_edge(&#34;generator&#34;, &#34;critic&#34;)
workflow.add_conditional_edges(&#34;critic&#34;, should_continue, 
    {&#34;generator&#34;: &#34;generator&#34;, END: END})

app = workflow.compile()

